contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will call Put(_lockTime) with some amount of Ether; check balances and log growth.
    function run(uint _lockTime, uint amount) public payable {
        require(address(this).balance >= amount);

        // Read prior observable state: holder balance via public mapping getter and contract balance and LogFile history length
        uint beforeHolderBalance = c.Acc(address(this)).balance;
        uint beforeContractBalance = address(c).balance;

        // Try to read LogFile address and its History length if possible
        address logAddr = address(c.LogFile());
        uint beforeHistoryLen = 0;
        if (logAddr != address(0)) {
            // history getter exists: History(uint) returns (Message) but there's also public History array -> length is available via calling History(uint) in a loop isn't possible here; however solidity provides automatic getter for public arrays returning single element; but we can get length via Log(logAddr).History(uint(0)) may revert if empty. So instead try to probe History length by calling LastMsg (which always exists) and optimistic approach: push will always increase History length by 1, so we record a flag whether LogFile is nonzero.
            beforeHistoryLen = 0; // unknown but we remember that log exists
        }

        // Perform the state-changing call: call Put with Ether amount. Capture whether it reverted.
        bool reverted;
        try c.Put{value: amount}(_lockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-state
        uint afterHolderBalance = c.Acc(address(this)).balance;
        uint afterContractBalance = address(c).balance;

        // If the call did not revert, then holder balance must have increased by amount and contract balance likewise.
        // Also, if LogFile was set (non-zero), Put always calls LogFile.AddMessage, which appends to History; we approximate this by requiring that when not reverted, contract balance increased by amount and holder balance increased by amount.
        assert(
            reverted || (afterHolderBalance == beforeHolderBalance + amount && afterContractBalance == beforeContractBalance + amount)
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Call Put with a lock time and send Ether amount; if it succeeds, Acc(this).balance and address(c).balance increase by amount.
    function run(uint _lockTime, uint amount) public payable {
        require(address(this).balance >= amount);

        // Read prior observable state: the Holder returned by public getter Acc(address) is a tuple (unlockTime, balance)
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint beforeContractBalance = address(c).balance;

        bool reverted;
        try c.Put{value: amount}(_lockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint afterContractBalance = address(c).balance;

        // If the call did not revert, holder.balance and contract balance must each increase by exactly amount.
        assert(reverted || (afterBalance == beforeBalance + amount && afterContractBalance == beforeContractBalance + amount));
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Try to collect _am from c for this contract's address; assert the observable invariant:
    // If Collect did not revert, then c.Acc(this).balance decreased by exactly _am and address(c).balance decreased by exactly _am.
    function run(uint _am) public payable {
        // No precondition on _am; but ensure this test contract has no reliance on msg.value.

        // Observe state before the call
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint beforeContractBalance = address(c).balance;

        bool reverted;
        try c.Collect{value: 0}(_am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint afterContractBalance = address(c).balance;

        // If Collect succeeded, then both the stored balance and contract balance must have decreased by exactly _am.
        // If Collect reverted, we make no claim (reverted == true).
        // Use a single assert as required.
        assert(reverted || (beforeBalance >= _am && beforeContractBalance >= _am && afterBalance + _am == beforeBalance && afterContractBalance + _am == beforeContractBalance));
    }

    receive() external payable { }
}

