    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Try to observe that when Collect succeeds, both the contract's ETH balance and
    // the caller's recorded balance decrease by exactly _am.
    // We must supply some prior state so Collect can potentially succeed: set MinSum = 0,
    // put some funds for this contract and set unlockTime in the past by using Put with 0 lock
    // (Put sets unlockTime to block.timestamp + 0 which equals now, and Collect requires block.timestamp > unlockTime,
    // so to ensure Collect can succeed, we will call Put then manually set intitalized and MinSum such that Collect may be allowed,
    // but since we cannot write internal vars, we instead rely on MinSum = 0 and that unlockTime becomes <= block.timestamp.

    // Note: To send Ether to c, we take amount parameters and ensure this contract has enough balance.
    function run(uint putAmount, uint _am) public payable {
        require(address(this).balance >= putAmount, "need funds to Put");

        // Ensure MinSum is zero so that MinSum check won't block Collect: call SetMinSum(0)
        // This call must be top-level and may revert if intitalized is true; for fresh c it will succeed.
        c.SetMinSum(0);

        // Put some funds under this contract's holder
        c.Put{value: putAmount}(0);

        // Observe balances before Collect
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        bool reverted;
        try c.Collect{value: 0}(_am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterContractBal = address(c).balance;
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));

        // If Collect succeeded, then both the contract balance and the recorded balance for this caller
        // must have decreased by exactly _am. If it reverted, we don't require changes.
        assert(reverted || (beforeContractBal == afterContractBal + _am && beforeBalance == afterBalance + _am));
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    function run(uint lockTime, uint amount) public payable {
        require(address(this).balance >= amount, "need funds to forward");

        // read balances before
        (uint beforeHolderUnlock, uint beforeHolderBalance) = getHolder(msg.sender);
        uint beforeContractBalance = address(c).balance;

        // perform Put with value 'amount', capture revert
        bool reverted;
        try c.Put{value: amount}(lockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read balances after
        (uint afterHolderUnlock, uint afterHolderBalance) = getHolder(msg.sender);
        uint afterContractBalance = address(c).balance;

        // If call succeeded: holder balance increased by amount and contract balance increased by amount.
        // If call reverted: both balances unchanged.
        assert(
            (reverted && afterHolderBalance == beforeHolderBalance && afterContractBalance == beforeContractBalance)
            || (!reverted && afterHolderBalance == beforeHolderBalance + amount && afterContractBalance == beforeContractBalance + amount)
        );
    }

    // helper to read the public struct mapping via the generated getter
    function getHolder(address a) internal view returns (uint unlockTime, uint balance) {
        // The compiler generates Acc(a) -> (uint unlockTime, uint balance)
        (unlockTime, balance) = c.Acc(a);
    }

    // receive to accept refunds if any
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    function run(uint am, uint lockTime, uint minSum, address logAddr) public payable {
        // need funds to call Put and to hold any required balance
        require(address(this).balance >= msg.value, "insufficient test balance");

        // initialize C: set MinSum and LogFile and mark initialized as needed
        // these calls may revert depending on C's state; they are top-level statements
        // SetMinSum and SetLogFile revert if already initialized; initial contract fresh so they should succeed
        c.SetMinSum(minSum);
        c.SetLogFile(logAddr);
        c.Initialized();

        // Ensure the test contract has some recorded balance: call Put forwarding `msg.value` to C
        // Use lockTime to set unlockTime possibly in future
        c.Put{value: msg.value}(lockTime);

        // Read pre-Collect observed values via public getters
        (uint preUnlock, uint preBalance) = c.Acc(address(this));
        uint preContractBal = address(c).balance;

        // Attempt Collect and record whether it reverted
        bool reverted;
        try c.Collect{value: 0}(am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read post-Collect observed values
        (uint postUnlock, uint postBalance) = c.Acc(address(this));
        uint postContractBal = address(c).balance;

        // General invariant: Collect either reverts leaving balances unchanged,
        // or succeeds decreasing both holder balance and contract balance by exactly am.
        // Note: unlockTime is not expected to increase due to Collect, so we also assert it unchanged.
        assert(
            (reverted && postBalance == preBalance && postContractBal == preContractBal && postUnlock == preUnlock)
            || (!reverted && preBalance >= am && postBalance + am == preBalance && postContractBal + am == preContractBal && postUnlock == preUnlock)
        );
    }

    // receive to accept Ether when this test contract is funded externally
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    // amount: Ether to send with Put; lockTime: parameter to Put; minSum and logAddr to initialize C
    function run(uint amount, uint lockTime, uint minSum, address logAddr) public payable {
        // ensure this test contract has the funds to send
        require(address(this).balance >= amount, "insufficient test balance");

        // Initialize C: set MinSum and LogFile and mark initialized so later calls don't revert due to init state
        c.SetMinSum(minSum);
        c.SetLogFile(logAddr);
        c.Initialized();

        // Observe pre-state: length of History and contract balance
        uint preHistLen = Log(logAddr).HistoryLength();
        // The Log contract in provided code exposes History as public array, so History.length getter exists.
        // However we must use c to read only c's public surface; we can read address(c).balance and also read LogFile via c.LogFile().
        // To strictly follow allowed observations, obtain the log address from c via its public getter LogFile().
        address observedLog = address(c.LogFile());
        uint preLen = Log(observedLog).HistoryLength();
        uint preContractBal = address(c).balance;

        // Call Put, capturing whether it reverted
        bool reverted;
        try c.Put{value: amount}(lockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe post-state
        address observedLog2 = address(c.LogFile());
        uint postLen = Log(observedLog2).HistoryLength();
        uint postContractBal = address(c).balance;

        // General rule: If Put succeeded then contract balance increased by amount and History.length increased by 1 on the current LogFile; if Put reverted then both stayed the same.
        assert(
            (reverted && postContractBal == preContractBal && observedLog2 == observedLog && postLen == preLen)
            || (!reverted && postContractBal == preContractBal + amount && observedLog2 == observedLog && postLen == preLen + 1)
        );
    }

    // Allow receiving Ether for the test harness
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function driving C.Put and asserting the general rule described above.
    // Parameters:
    // - amount: wei to send with Put (must be available in this contract's balance)
    // - lockTime: the _lockTime argument passed to Put
    // - minSum: value to set MinSum in C before Initialized
    // - logAddr: address of a Log contract to set as C.LogFile
    function run(uint amount, uint lockTime, uint minSum, address logAddr) public payable {
        require(address(this).balance >= amount, "insufficient test balance");

        // Initialize C so SetMinSum/SetLogFile/Initialized can be called and later Put won't revert due to initialization guard
        c.SetMinSum(minSum);
        c.SetLogFile(logAddr);
        c.Initialized();

        // Observe pre-state: contract balance and Log.History.length via the Log public getter on the LogFile address
        uint preCbalance = address(c).balance;
        // Read current LogFile address from c's public variable getter
        address currentLog = address(c.LogFile());
        // Read History.length of the Log contract at currentLog via the auto-generated getter History(uint)
        // History is an array of Message; its length can be read by calling History(uint256) is not available, but the compiler generates a .History(uint) accessor for elements and a .HistoryLength is not present.
        // However Solidity exposes the array length via the automatically generated getter named History that has a .length field accessible only in code; since we cannot access that, instead we read History(0) conditionally to detect length changes.
        // To get a reliable length, we will attempt to read an element at index i in increasing order until a call reverts; but view external calls revert into try/catch, which we cannot use inside an assert. Simpler approach: rely on LogFile.History.length via low-level staticcall to the public getter signature "history(uint256)" isn't allowed. Instead, the Log contract's History array has a public getter History(uint) returning (address,string,uint,uint).
        // We'll probe a single index: try index 0; if it exists before and after, and we detect change by checking History(0).Time and .Val etc. But that is brittle. A safer technique: call the public function LastMsg (public variable LastMsg) does exist and is public, so c.LogFile().LastMsg() returns the last pushed message. The contract defines LastMsg as public variable, so there is a getter LastMsg() returning the Message struct. We'll use LastMsg as a proxy: if Put succeeds it sets LastMsg to the new entry and pushes to History; therefore LastMsg should reflect the last operation only if the LogFile address stays the same.

        // Read pre LastMsg fields via the Log getter on currentLog
        Log log = Log(currentLog);
        (address preSender, string memory preData, uint preVal, uint preTime) = log.LastMsg();

        bool reverted;
        // Call Put and catch revert
        try c.Put{value: amount}(lockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe post-state
        uint postCbalance = address(c).balance;
        address postLogAddr = address(c.LogFile());
        Log postLog = Log(postLogAddr);
        (address postSender, string memory postData, uint postVal, uint postTime) = postLog.LastMsg();

        // Assert the general rule:
        // - If reverted: contract balance unchanged and LastMsg remained identical (no new log entry on current LogFile)
        // - If succeeded: contract balance increased by amount and LastMsg reflects a new entry with Sender == address(this) and Val == amount (Put logs msg.sender and msg.value)
        assert(
            (reverted && postCbalance == preCbalance && postLogAddr == currentLog && postSender == preSender && keccak256(bytes(postData)) == keccak256(bytes(preData)) && postVal == preVal && postTime == preTime)
            ||
            (!reverted && postCbalance == preCbalance + amount && postLogAddr == currentLog && postSender == address(this) && postVal == amount)
        );
    }

    // Allow receiving Ether for the test harness
    receive() external payable {}
}

