            reverted = true;
        }

        // Observe post-state
        uint postCbalance = address(c).balance;
        (address postSender, string memory postData, uint postVal, uint postTime) = log.LastMsg();

        // General invariant:
        // If the call reverted then C's balance and Log.LastMsg must be unchanged.
        // If it succeeded then C's balance increases by amount and Log.LastMsg is updated with Sender == address(this) and Val == amount.
        assert(
