contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will try to Put some value and then attempt Collect; inputs:
    // lockTime: uint to pass to Put; putAmount: Ether sent with Put;
    // collectAmount: amount attempted to Collect.
    function run(uint lockTime, uint putAmount, uint collectAmount) public payable {
        require(address(this).balance >= putAmount, "insufficient test balance for Put");
        // Ensure MinSum and log file set so Collect may rely on them; set MinSum to 0 and set a Log contract
        // Deploying new Log is not allowed; but contract c has SetLogFile and SetMinSum that accept values.
        // We only observe through getters; calling SetLogFile with address(this) (allowed) and SetMinSum.
        // Both functions revert if c.intitalized is true; c is fresh per constraints so okay.
        c.SetMinSum(0);
        c.SetLogFile(address(this));

        // Record balances before
        uint beforeAccBalance = c.Acc(address(this)).balance; // getter Acc(address).balance
        uint beforeContractBal = address(c).balance;

        // Perform Put sending ETH
        c.Put{value: putAmount}(lockTime);

        // After Put, check balances
        uint afterAccBalance = c.Acc(address(this)).balance;
        uint afterContractBal = address(c).balance;

        // Now attempt Collect. We need to capture whether it reverted.
        bool reverted;
        // ensure msg.sender (this contract) can call Collect on behalf of itself; c expects msg.sender to be holder
        try c.Collect{value: 0}(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read balances after Collect attempt
        uint finalAccBalance = c.Acc(address(this)).balance;
        uint finalContractBal = address(c).balance;

        // General property: If Collect did NOT revert, then (1) finalAccBalance = afterAccBalance - collectAmount
        // and (2) finalContractBal = afterContractBal - collectAmount. If Collect reverted, balances unchanged.
        assert(
            (!reverted && finalAccBalance == afterAccBalance - collectAmount && finalContractBal == afterContractBal - collectAmount)
            || (reverted && finalAccBalance == afterAccBalance && finalContractBal == afterContractBal)
        );
    }

    // Provide a minimal fallback to accept LogFile.AddMessage calls if c tries to call this contract as a Log.
    receive() external payable { }
}

