    function run(uint lockTime, uint putAmount, uint collectAmount) public payable {
        require(address(this).balance >= putAmount, "insufficient test balance for Put");

        // Initialize c so that Put/Collect and logging work: set MinSum to 0 and set LogFile to this address
        // These calls revert if already initialized; c is fresh per harness so these should succeed
        c.SetMinSum(0);
        c.SetLogFile(address(this));

        // Record balances before Put
        // Acc getter returns (uint unlockTime, uint balance) as a tuple; we read the second element by calling the getter and capturing it
        (uint beforeUnlock, uint beforeAccBal) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // Perform Put sending Ether
        c.Put{value: putAmount}(lockTime);

        // Read balances after Put
        (uint afterUnlock, uint afterAccBal) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // Attempt Collect and record whether it reverted
        bool reverted;
        try c.Collect{value: 0}(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read balances after Collect attempt
        (uint finalUnlock, uint finalAccBal) = c.Acc(address(this));
        uint finalContractBal = address(c).balance;

        // Assert the invariant: if Collect succeeded then Acc balance decreased exactly by collectAmount and contract balance decreased by same amount;
        // if Collect reverted then balances unchanged from after Put.
        assert(
            (!reverted && finalAccBal == afterAccBal - collectAmount && finalContractBal == afterContractBal - collectAmount)
            || (reverted && finalAccBal == afterAccBal && finalContractBal == afterContractBal)
        );
    }

    // Minimal receiver so c can call this as Log contract if needed
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will call SetMinSum and SetLogFile, then call Put with some Ether, and assert a relation
    // between Acc balance and address(c).balance that must hold for all inputs.
    // Parameters: lockTime for Put, putAmount to send with Put.
    function run(uint lockTime, uint putAmount) public payable {
        // ensure this test contract has enough funds to send
        require(address(this).balance >= putAmount);

        // initialize c: these should succeed on a fresh c
        c.SetMinSum(0);
        c.SetLogFile(address(this));

        // read balances before Put
        (uint beforeUnlock, uint beforeAccBal) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // perform Put sending Ether
        c.Put{value: putAmount}(lockTime);

        // read balances after Put
        (uint afterUnlock, uint afterAccBal) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // General rule to assert (single assert):
        // 1) The Acc balance recorded for this address never decreases as a result of Put (it may increase by at least 0).
        // 2) The contract's Ether balance increased by at most the same amount as Acc balance increased.
        // This avoids risky subtraction in the assert by using comparisons arranged to be safe.
        assert(
            // Acc did not decrease
            afterAccBal >= beforeAccBal
            // contract balance did not increase more than Acc increase
            && (afterContractBal - beforeContractBal) <= (afterAccBal - beforeAccBal)
        );
    }

    // Allow receiving Ether as Log target
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will call Initialized(), then attempt SetMinSum and observe that it must revert.
    // Parameters: a value to pass to SetMinSum when testing revert behavior.
    function run(uint newMin) public payable {
        // First ensure we can call SetLogFile and SetMinSum once before initialization to set up state.
        // Those calls on a fresh c should succeed; call SetMinSum and SetLogFile once to mimic normal setup.
        c.SetMinSum(1);
        c.SetLogFile(address(this));

        // Now call Initialized() to flip the internal flag.
        c.Initialized();

        // Try calling SetMinSum after initialization and capture whether it reverts.
        bool reverted;
        try c.SetMinSum(newMin) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After Initialized() was called, SetMinSum MUST revert (because intitalized becomes true and SetMinSum reverts if intitalized).
        assert(reverted == true);
    }

    // Provide receive so SetLogFile(address(this)) can be used as a Log target if it sends Ether (it doesn't),
    // and to satisfy the constraint that this contract can accept Ether if needed by other interactions.
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will test Put and Collect behavior. We take params for putAmount, lockTime, and collectAmount.
    // Note: msg.sender for calls to c will be this contract.
    function run(uint putAmount, uint lockTime, uint collectAmount) public payable {
        require(address(this).balance >= putAmount, "not enough balance to send");

        // Read initial values
        (uint beforeBalance,) = (c.Acc(address(this)).balance, c.Acc(address(this)).unlockTime);
        uint beforeContractBal = address(c).balance;

        // Perform Put by calling fallback (which calls Put(0)), if putAmount > 0 we call Put explicitly
        if (putAmount > 0) {
            c.Put{value: putAmount}(lockTime);
        } else {
            // call fallback to exercise fallback path
            (bool sent,) = address(c).call{value: 0}("");
            sent; // ignore
        }

        // After Put, the public getter Acc(address(this)) should reflect increased balance
        // Access the public struct getter: Acc returns (uint unlockTime, uint balance) per solidity ordering
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // Try Collect and record whether it reverts
        bool collectReverted;
        try c.Collect(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Now assert a general invariant: 1) after Put the contract's balance increased by >= putAmount
        // 2) the getter balance equals the observed delta for this holder (i.e., afterBalance >= beforeBalance)
        // 3) If Collect did not revert then the conditions required by Collect must have been true per public getters
        //    (holder balance before collect >= MinSum, >= collectAmount, and block.timestamp > unlockTime)
        uint deltaContract = afterContractBal - beforeContractBal; // no underflow since balance can only increase by put
        bool rule1 = deltaContract >= putAmount;
        bool rule2 = afterBalance >= beforeBalance;

        uint minSum = c.MinSum();
        // Note: We cannot read acc balance at the exact moment before Collect, but afterBalance is the balance before Collect's effects
        bool collectConditions = (afterBalance >= minSum) && (afterBalance >= collectAmount) && (block.timestamp > afterUnlock);

        // If collect did not revert, then collectConditions must hold. Conversely if collectConditions hold, Collect should not necessarily succeed (e.g., reentrancy or external call could fail), but P's code only requires those three conditions to permit transfer.
        // Our assert enforces that whenever Collect returned (didn't revert), the public-observable conditions were met.
        assert(rule1 && rule2 && (!collectReverted || collectConditions));
    }

    // Allow receiving ETH for funding putAmount
    receive() external payable {}
}

