    // run performs one Put (possibly via fallback) and then attempts Collect, checking observable balances.
    // Params: putAmount - ETH to send to Put; lockTime - parameter for Put; collectAmount - argument for Collect.
    function run(uint putAmount, uint lockTime, uint collectAmount) public payable {
        // ensure this test contract has funds to send
        require(address(this).balance >= putAmount, "insufficient test balance");

        // Read holder state before Put via public getter: Acc returns (unlockTime, balance)
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;
        uint beforeThisBal = address(this).balance;

        // Perform Put: call Put with value putAmount
        c.Put{value: putAmount}(lockTime);

        // Read after Put
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;
        uint afterThisBal = address(this).balance;

        // Try Collect and record whether it reverted. If it returns, record balances after call.
        bool collectReverted;
        uint postCollectHolderBal = afterBalance;
        uint postCollectContractBal = afterContractBal;
        uint postCollectThisBal = afterThisBal;
        try c.Collect(collectAmount) {
            collectReverted = false;
            // read public values after successful Collect
            (uint auc, uint abc) = c.Acc(address(this));
            postCollectHolderBal = abc;
            postCollectContractBal = address(c).balance;
            postCollectThisBal = address(this).balance;
        } catch {
            collectReverted = true;
        }

        // General invariant to assert:
        // 1) The contract's balance increased by at least putAmount.
        // 2) The holder's reported balance after Put is >= beforeBalance.
        // 3) If Collect did not revert then holder balance decreased by exactly collectAmount and this contract's balance increased by exactly collectAmount.
        bool rule1 = (afterContractBal >= beforeContractBal) && (afterContractBal - beforeContractBal >= putAmount);
        bool rule2 = (afterBalance >= beforeBalance);
        bool rule3;
        if (!collectReverted) {
            // require that observed changes equal collectAmount
            // postCollectHolderBal was read after Collect; before that it was afterBalance
            // postCollectThisBal - afterThisBal should equal collectAmount
            // postCollectHolderBal + collectAmount == afterBalance
            bool holderDec = (afterBalance >= postCollectHolderBal) && (afterBalance - postCollectHolderBal == collectAmount);
            bool thisInc = (postCollectThisBal >= afterThisBal) && (postCollectThisBal - afterThisBal == collectAmount);
            rule3 = holderDec && thisInc;
        } else {
            // if it reverted we don't require these equalities
            rule3 = true;
        }

        assert(rule1 && rule2 && rule3);
    }

