        uint contractBalBefore = address(c).balance;
        uint thisBalBefore = address(this).balance;

        // Attempt Collect and record whether it reverted. If it succeeded, read post-state.
        bool collectReverted;
        uint balAfter = balBefore;
        uint contractBalAfter = contractBalBefore;
        uint thisBalAfter = thisBalBefore;
        try c.Collect(collectAmount) {
            collectReverted = false;
            (uint unlockA, uint balA) = c.Acc(address(this)); balAfter = balA;
            contractBalAfter = address(c).balance;
            thisBalAfter = address(this).balance;
        } catch {
            collectReverted = true;
        }

