    // Inputs: amount to deposit (putAmt), lockTime for Put, amount to collect (collectAmt).
    // The test asserts that if Collect succeeded then address(c).balance decreased by collectAmt
    // and Acc[msg.sender].balance (via public getter) decreased by collectAmt. If Collect reverted,
    // then at least one of the three required preconditions for success was violated.

    receive() external payable { }

    function run(uint putAmt, uint lockTime, uint collectAmt) public payable {
        // require we can send the deposit and possible collect (collect is sent out by c to this contract)
        // We only need balance for outgoing deposit; collectAmt will be sent by c to this contract if successful.
        require(address(this).balance >= putAmt, "insufficient test balance");

        // Ensure MinSum is zero so it doesn't block unless balance < collectAmt; set before Initialized.
        // SetMinSum is nonReentrant_ and must not have been Initialized yet; ctor of C leaves it false.
        c.SetMinSum(0);

        // Read c state before Put
        uint beforeContractBalance = address(c).balance;
        (uint beforeUnlockTime, uint beforeBalance) = getAcc();

        // Perform Put by sending putAmt wei
        c.Put{value: putAmt}(lockTime);

        // Read state after Put
        uint afterContractBalance = address(c).balance;
        (uint afterUnlockTime, uint afterBalance) = getAcc();

        // Sanity: afterContractBalance should have increased by putAmt
        // (this is not part of final assert but helps ensure test path is meaningful)

        // Now try Collect and record whether it reverted.
        bool reverted;
        // capture balances of this test contract before collect attempt
        uint beforeThisBal = address(this).balance;
        (bool success, ) = address(c).call(abi.encodeWithSelector(C.Collect.selector, collectAmt));
        // The above low-level call will not propagate revert; success==false means reverted.
        reverted = !success;
        uint afterThisBal = address(this).balance;
        uint finalContractBalance = address(c).balance;
        (uint finalUnlockTime, uint finalBalance) = getAcc();

        // Build the logical condition to assert:
        // If Collect succeeded (not reverted) then:
        //  - contract balance decreased by collectAmt
        //  - this contract's balance increased by collectAmt
        //  - Acc[msg.sender].balance decreased by collectAmt
        // If Collect reverted then at least one of these holds: beforeBalance < c.MinSum(), beforeBalance < collectAmt, block.timestamp <= beforeUnlockTime

        // Note: we can read MinSum via public getter and Acc via public getter getAcc().
        uint minSum = c.MinSum();

        bool successCase;
        if (!reverted) {
            bool contractDec = (beforeContractBalance == finalContractBalance + collectAmt);
            bool thisInc = (afterThisBal == beforeThisBal + collectAmt);
            bool accDec = (afterBalance == finalBalance + collectAmt) || (beforeBalance == finalBalance + collectAmt);
            // accDec checks that the Acc balance decreased by collectAmt relative to either before or after read
            successCase = contractDec && thisInc && accDec;
        } else {
            // One of the necessary preconditions must have failed.
            bool cond1 = beforeBalance < minSum;
            bool cond2 = beforeBalance < collectAmt;
            bool cond3 = block.timestamp <= beforeUnlockTime;
            successCase = (cond1 || cond2 || cond3);
        }

        assert(successCase);
    }

    // Helper to read Acc[msg.sender] public getter which returns (unlockTime, balance)
    function getAcc() internal view returns (uint, uint) {
        // The auto-generated getter has signature: function Acc(address) public view returns (uint unlockTime, uint balance);
        return c.Acc(address(this));
    }
}

