        (bool success, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", collectAmt));
        collectReverted = !success;

        // Read after Collect
        (uint finalUnlock, uint finalBal) = c.Acc(address(this));
        uint finalContractBal = address(c).balance;

        // If Collect succeeded then contract must have sent exactly collectAmt to this contract
        // i.e., contract balance decreased by collectAmt and recorded balance decreased by collectAmt
        bool collect_succeeded_impacts = true;
        if (!collectReverted) {
            // contract balance decreased by collectAmt
            bool cb = (finalContractBal + collectAmt == beforeCollectContractBal);
            // stored balance decreased by collectAmt
            bool sb = (finalBal + collectAmt == afterBal);
            collect_succeeded_impacts = cb && sb;
        } else {
            // If collect reverted, then at least one of conditions for success must have failed:
            // (afterBal >= beforeMin) && (afterBal >= collectAmt) && (block.timestamp > afterUnlock)
            // We can only observe afterBal, beforeMin, afterUnlock and current block.timestamp via solidity but block.timestamp is allowed.
            bool cond_balance_min = (afterBal >= beforeMin);
            bool cond_balance_amount = (afterBal >= collectAmt);
            bool cond_unlock = (block.timestamp > afterUnlock);
            // For a revert, at least one of these is false
            collect_succeeded_impacts = !(cond_balance_min && cond_balance_amount && cond_unlock);
        }

        // Final general assert: Put observable effects held, and the implication about Collect holds
        assert(put_balance_increased && contract_balance_increased && collect_succeeded_impacts);
    }

    // receive to accept any refunds or transfers (if Collect sends to this contract)
    receive() external payable {}
}

