    // This test uses two candidate values for MinSum and checks SetMinSum behavior.
    // Params:
    //  v1, v2 - two uint values passed to SetMinSum in sequence
    function run(uint v1, uint v2) public payable {
        // No precondition on c; use try/catch to observe reverts.

        // Attempt first SetMinSum
        bool firstReverted;
        try c.SetMinSum(v1) {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        // Read MinSum after first attempt
        uint afterFirstMin = c.MinSum();

        // Attempt second SetMinSum with possibly different value
        bool secondReverted;
        try c.SetMinSum(v2) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        // Read MinSum after second attempt
        uint afterSecondMin = c.MinSum();

        // Attempt to call Initialized to flip initialized flag (may revert if reentrancy guard or other issues, but it's external nonReentrant_ and should succeed here)
        bool initReverted;
        try c.Initialized() {
            initReverted = false;
        } catch {
            initReverted = true;
        }

        // Read MinSum after Initialized
        uint afterInitMin = c.MinSum();

        // General rule to assert:
        // - If the first SetMinSum succeeded then afterFirstMin equals v1.
        // - If the first SetMinSum reverted then afterFirstMin equals its previous value (which for fresh c is 0), so we assert it wasn't changed to v1.
        // - If the first succeeded then the second must revert (cannot change MinSum again), so secondReverted must be true and afterSecondMin == afterFirstMin.
        // - After Initialized (if it succeeded), MinSum must remain equal to afterSecondMin (Initialized does not change MinSum itself).

        assert(
            // first attempt consistency
            ((firstReverted && afterFirstMin != v1) || (!firstReverted && afterFirstMin == v1))
            // if first succeeded then second must revert and not change value
            && (( !firstReverted ) ? (secondReverted && afterSecondMin == afterFirstMin) : true)
            // Initialized does not change MinSum (whether init reverted or not, MinSum after init equals before init)
            && (afterInitMin == afterSecondMin)
        );
    }

    receive() external payable {}
}

