contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will call Put through payable call and check that address(c).balance increases by amount
    // and that the Log contract's History array length increases by at least 1 (we observe by calling LogFile() getter then History(uint) getter length is not directly available,
    // but Log has public History array so we can probe an index that should exist after the call. To avoid assuming a starting length, we read address(c).balance before and after and
    // also attempt to read the last message that should have been pushed; we'll assert balance increased by amount and that reading the last History entry returns the expected values' Sender equals address(this) and Val equals amount.

    // Note: We interact only through public surface. The test function is payable and takes the amount and lockTime as inputs.
    function run(uint lockTime, uint amount) public payable {
        require(address(this).balance >= amount, "insufficient test balance");
        // read c balance before
        uint balBefore = address(c).balance;

        // read MinSum to avoid any dependency (just an observable read)
        uint minBefore = c.MinSum();

        // call Put forwarding Ether
        c.Put{value: amount}(lockTime);

        // read balance after
        uint balAfter = address(c).balance;

        // read LogFile address and then probe its last message
        address logAddr = address(c.LogFile());

        // If no LogFile was set, its address may be zero; in that case no message could have been recorded. We assert a general rule that if a LogFile is set (non-zero), then Put increases c balance by amount and appends a History message whose Sender is address(this) and Val==amount.
        // Try reading the last message only when logAddr != address(0)

        bool logIsSet = (logAddr != address(0));

        // If log is set, we can call the Log contract's public History getter. The History array has elements of type (address,string,uint,uint).
        (address histSender, string memory histData, uint histVal, uint histTime) = (address(0), "", uint(0), uint(0));
        if (logIsSet) {
            // The History array length is not directly exposed, but pushing a message means the last index is some i. We don't know i; however AddMessage pushes one element so we can attempt to read index 0 and if it exists then also read a high index until we find a matching entry.
            // Simpler approach: after Put we expect that at least one message exists and that some entry has Sender == address(this) and Val == amount. We'll search indices 0..3 for such an entry.
            // Note: public array getter History(uint) returns (address,string,uint,uint)
            for (uint i = 0; i < 4; i++) {
                // We must avoid reverting when index out of bounds; calling the public array getter with out-of-range index will revert, so we catch by using try/catch on external call via low-level interface.
                // But we cannot instantiate interfaces here. Instead we will attempt to call via (Log)(logAddr).History(i) by using the known contract type Log — not allowed to redeclare, but Log exists in compilation unit, so we can use Log type.
                // Use try/catch to avoid revert aborting the whole test.
                try Log(logAddr).History(i) returns (address s, string memory d, uint v, uint t) {
                    if (s == address(this) && v == amount) {
                        histSender = s;
                        histData = d;
                        histVal = v;
                        histTime = t;
                        break;
                    }
                } catch {
                    // ignore out-of-bounds
                }
            }
        }

        // Now assert the general rule: if LogFile was set, then c's balance increased by amount and there exists a recent History entry with Sender==address(this) and Val==amount.
        // If LogFile not set, we only assert that c.balance increased by amount (Put should still transfer funds into c regardless of LogFile presence).

        if (logIsSet) {
            assert(balAfter == balBefore + amount && histSender == address(this) && histVal == amount);
        } else {
            assert(balAfter == balBefore + amount);
        }
    }

    receive() external payable {}
}

