        bool contractIncreasedBy = (contractBalAfter >= contractBalBefore) && (contractBalAfter - contractBalBefore == putAmount);
        bool holderIncreasedAtLeast = (holderBalAfter >= holderBalBefore) && ((holderBalAfter - holderBalBefore) >= putAmount);
        bool unlockNonDecreasing = (unlockAfter >= unlockBefore);

        assert(contractIncreasedBy && holderIncreasedAtLeast && unlockNonDecreasing);
    }

    receive() external payable {}
}

contract InvMutTest {
