    constructor(C _c) { c = _c; }

    // params:
    // putAmount: wei to send in Put
    // lockTime: lock time passed to Put
    function run(uint putAmount, uint lockTime) public payable {
        require(address(this).balance >= putAmount, "need funds for Put");

        // Observe before-values
        uint contractBalBefore = address(c).balance;
        (uint unlockBefore, uint holderBalBefore) = c.Acc(address(this));

        // Perform Put and capture whether it reverted
        bool reverted;
        try c.Put{value: putAmount}(lockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values (even if reverted, getters still callable)
        uint contractBalAfter = address(c).balance;
        (uint unlockAfter, uint holderBalAfter) = c.Acc(address(this));

        // If Put returned (did not revert) then contract balance must have increased by exactly putAmount
        // and the recorded holder balance must have increased by at least putAmount, and unlockTime is non-decreasing.
        // We assert the implication: not reverted => (contractBalAfter - contractBalBefore == putAmount && holderBalAfter >= holderBalBefore && unlockAfter >= unlockBefore)

        // To avoid underflow in the assert when reverted = true we write implication as: reverted || (conditions)
        assert(reverted || ((contractBalAfter >= contractBalBefore) && (contractBalAfter - contractBalBefore == putAmount) && (holderBalAfter >= holderBalBefore) && (unlockAfter >= unlockBefore)));
    }

    receive() external payable {}
}

