}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that drives the contract and asserts the invariant
    function run(uint lockTime, uint putAmount, uint collectAmount) public payable {
        // ensure this contract has enough balance to forward putAmount
        require(address(this).balance >= putAmount);

        // read balances before any operations
        uint before_contract_balance = address(c).balance;
        (uint before_unlock, uint before_balance) = getHolder(msg.senderAlias());

        // perform Put by forwarding Ether
        c.Put{value: putAmount}(lockTime);

        // read after Put
        uint mid_contract_balance = address(c).balance;
        (uint after_unlock, uint after_balance) = getHolder(msg.senderAlias());

        // basic expected effect of Put: contract balance increased by putAmount
        bool put_contract_balance_ok = (mid_contract_balance == before_contract_balance + putAmount);
        // and recorded holder balance increased by putAmount
        bool put_holder_balance_ok = (after_balance == before_balance + putAmount);

        // Attempt Collect and observe whether it reverts
        bool collect_reverted;
        try c.Collect{value: 0}(collectAmount) {
            collect_reverted = false;
        } catch {
            collect_reverted = true;
        }

        // read after Collect
        uint final_contract_balance = address(c).balance;
        (uint final_unlock, uint final_balance) = getHolder(msg.senderAlias());

        // If Collect did not revert then it must have sent collectAmount out and reduced both
        // the on-chain contract ETH balance and the stored holder balance by collectAmount.
        // If it reverted then balances must be unchanged from mid state.
        bool collect_effects_ok = collect_reverted ?
            (final_contract_balance == mid_contract_balance && final_balance == after_balance)
            : (final_contract_balance + collectAmount == mid_contract_balance && after_balance == final_balance + collectAmount);

        assert(put_contract_balance_ok && put_holder_balance_ok && collect_effects_ok);
    }

    // helper to call the public getter Acc (auto-generated struct getter has two return values)
    // The C contract's Acc getter signature is (uint unlockTime, uint balance)
    function getHolder(address adr) internal view returns (uint, uint) {
        // Note: c.Acc(adr) is a public getter with two uint returns
        return c.Acc(adr);
    }

    // Because when this test contract calls c, msg.sender inside C will be this contract.
    function msg.senderAlias() internal view returns (address) {
        return address(this);
    }

    // allow receiving Ether so Put can send back via fallback or Collect can transfer to this contract
    receive() external payable { }
}

